<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ArrowRight, Database, Eye, EyeOff, FileUp, Pencil, Plus, Save, Search, Trash2, X } from 'lucide-vue-next'
import AdminModuleHeader from '../components/AdminModuleHeader.vue'
import { api } from '../api'

type CityRow = { id: number; slug: string; name: string; aliases: string[]; description: string; season: string; budget: string; recommended_days: string; image_url: string; support_level: string; planning_enabled: boolean; is_active: boolean; attraction_count: number }
type CityForm = Omit<CityRow, 'id' | 'attraction_count' | 'aliases'> & { aliases: string }
const emptyForm = (): CityForm => ({ slug: '', name: '', aliases: '', description: '', season: '', budget: '', recommended_days: '', image_url: '', support_level: 'full', planning_enabled: true, is_active: true })
const cities = ref<CityRow[]>([]); const search = ref(''); const error = ref(''); const notice = ref(''); const editingId = ref<number | null>(null); const form = ref<CityForm>(emptyForm()); const showImport = ref(false); const saving = ref(false)
const importText = ref('[\n  {\n    "slug": "hangzhou",\n    "name": "杭州",\n    "description": "城市介绍",\n    "season": "春秋",\n    "budget": "¥300-600/天",\n    "recommended_days": "2-3天"\n  }\n]')
const filteredCities = computed(() => { const keyword = search.value.trim().toLowerCase(); return keyword ? cities.value.filter((city) => `${city.name} ${city.slug} ${city.description}`.toLowerCase().includes(keyword)) : cities.value })
function toPayload() { return { ...form.value, aliases: form.value.aliases.split(/[,，]/).map((item) => item.trim()).filter(Boolean) } }
function edit(city?: CityRow) { editingId.value = city?.id ?? null; form.value = city ? { ...city, aliases: city.aliases.join(', ') } : emptyForm(); notice.value = '' }
async function loadCities() { cities.value = await api<CityRow[]>('/admin/cities') }
async function save() { saving.value = true; notice.value = ''; try { const message = editingId.value ? '城市资料已保存' : '城市已新增'; const path = editingId.value ? `/admin/cities/${editingId.value}` : '/admin/cities'; await api(path, { method: editingId.value ? 'PATCH' : 'POST', body: JSON.stringify(toPayload()) }); await loadCities(); edit(); notice.value = message } catch (exception) { notice.value = exception instanceof Error ? exception.message : '保存失败' } finally { saving.value = false } }
async function toggleActive(city: CityRow) { const action = city.is_active ? '停用' : '启用'; if (!window.confirm(`确定${action}城市“${city.name}”吗？`)) return; try { await api(`/admin/cities/${city.id}`, { method: 'PATCH', body: JSON.stringify({ is_active: !city.is_active }) }); await loadCities(); notice.value = `城市已${action}` } catch (exception) { notice.value = exception instanceof Error ? exception.message : `${action}失败` } }
async function remove(city: CityRow) { if (!window.confirm(`确定彻底删除城市“${city.name}”吗？此操作不能撤销，存在任何关联数据时系统会拒绝。`)) return; try { await api(`/admin/cities/${city.id}`, { method: 'DELETE' }); await loadCities(); notice.value = '城市已彻底删除' } catch (exception) { notice.value = exception instanceof Error ? exception.message : '删除失败' } }
async function importCities() { try { const items = JSON.parse(importText.value); if (!Array.isArray(items)) throw new Error('导入内容必须是 JSON 数组'); await api('/admin/cities/import', { method: 'POST', body: JSON.stringify({ items }) }); await loadCities(); notice.value = `已导入 ${items.length} 个城市`; showImport.value = false } catch (exception) { notice.value = exception instanceof Error ? exception.message : '导入失败' } }
onMounted(async () => { try { await loadCities() } catch (exception) { error.value = exception instanceof Error ? exception.message : '加载失败' } })
</script>

<template><div class="page-container"><AdminModuleHeader eyebrow="DESTINATIONS" title="城市管理" description="维护目的地资料、上架状态、规划状态和景点覆盖情况。" /><div v-if="error" class="empty-state"><Database :size="28" /><h2>{{ error }}</h2></div><template v-else><div class="admin-toolbar"><span class="admin-result-count">{{ filteredCities.length }} 个城市</span><div class="admin-toolbar-group"><button class="secondary-button" @click="showImport = !showImport"><FileUp :size="16" />批量导入</button><button class="primary-button" @click="edit()"><Plus :size="16" />新增城市</button><input v-model="search" class="admin-search" placeholder="搜索城市或介绍" /></div></div><p v-if="notice" class="admin-notice">{{ notice }}</p><section class="admin-editor"><div class="admin-editor-heading"><h2>{{ editingId ? '编辑城市' : '新增城市' }}</h2><button class="admin-table-action" title="关闭编辑" @click="edit()"><X :size="16" /></button></div><div class="admin-form-grid"><label>英文标识<input v-model="form.slug" placeholder="hangzhou" /></label><label>城市名称<input v-model="form.name" placeholder="杭州" /></label><label>别名（逗号分隔）<input v-model="form.aliases" /></label><label>最佳季节<input v-model="form.season" /></label><label>预算参考<input v-model="form.budget" /></label><label>建议天数<input v-model="form.recommended_days" /></label><label>图片地址<input v-model="form.image_url" /></label><label>支持等级<input v-model="form.support_level" /></label><label class="admin-form-wide">城市介绍<textarea v-model="form.description" rows="3" /></label><label class="admin-check"><input v-model="form.is_active" type="checkbox" />在前台展示</label><label class="admin-check"><input v-model="form.planning_enabled" type="checkbox" />允许 AI 规划</label></div><button class="primary-button" :disabled="saving" @click="save"><Save :size="16" />{{ saving ? '保存中' : '保存城市' }}</button></section><section v-if="showImport" class="admin-editor"><div class="admin-editor-heading"><h2>批量导入城市</h2><button class="admin-table-action" title="关闭导入" @click="showImport = false"><X :size="16" /></button></div><textarea v-model="importText" class="admin-json-input" rows="12" aria-label="城市 JSON 导入内容" /><button class="primary-button" @click="importCities"><FileUp :size="16" />导入 JSON</button></section><div class="admin-table-wrap"><table class="admin-data-table"><thead><tr><th>城市</th><th>内容状态</th><th>规划状态</th><th>支持等级</th><th>建议天数</th><th>预算参考</th><th>景点</th><th aria-label="操作"></th></tr></thead><tbody><tr v-for="city in filteredCities" :key="city.id"><td><strong>{{ city.name }}</strong><small>{{ city.slug }} · {{ city.description }}</small></td><td><span :class="['admin-status', { muted: !city.is_active }]">{{ city.is_active ? '已上架' : '已停用' }}</span></td><td><span :class="['admin-status', { muted: !city.planning_enabled }]">{{ city.planning_enabled ? '可规划' : '不可规划' }}</span></td><td>{{ city.support_level }}</td><td>{{ city.recommended_days }}</td><td>{{ city.budget }}</td><td>{{ city.attraction_count }} 个</td><td class="admin-table-actions"><button class="admin-table-action" title="编辑城市" @click="edit(city)"><Pencil :size="16" /></button><RouterLink class="admin-table-action" :to="`/admin/attractions?city=${city.id}`" title="查看城市景点"><ArrowRight :size="16" /></RouterLink><button class="admin-table-action" :title="city.is_active ? '停用城市' : '启用城市'" @click="toggleActive(city)"><EyeOff v-if="city.is_active" :size="16" /><Eye v-else :size="16" /></button><button v-if="!city.is_active" class="admin-table-action danger-action" title="彻底删除城市" @click="remove(city)"><Trash2 :size="16" /></button></td></tr></tbody></table><div v-if="!filteredCities.length" class="admin-page-empty"><Search :size="20" /><p>没有匹配的城市</p></div></div></template></div></template>
